import math
def are_coprime(a, b):
    return math.gcd(a, b) == 1

def is_squarefree(n):
    x = n
    p = 2
    while p * p <= x:
        if x % (p * p) == 0:
            return False
        while x % p == 0:
            x //= p
        p += 1
    return True

def recaman(n):
    seen = {0}
    a = 0
    for k in range(1, n + 1):
        prev = a - k
        if prev > 0 and prev not in seen:
            a = prev
        else:
            a = a + k
        seen.add(a)
    return a

import math
def is_sum_of_two_squares(n):
    a = 0
    while a * a <= n:
        b2 = n - a * a
        b = math.isqrt(b2)
        if b * b == b2:
            return True
        a += 1
    return False

def digital_root_base(n, b):
    while n >= b:
        s = 0
        x = n
        while x > 0:
            s += x % b
            x //= b
        n = s
    return n

def is_self_number(n):
    lo = max(0, n - 100)
    for m in range(lo, n):
        if m + sum(int(d) for d in str(m)) == n:
            return False
    return True

def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    rev = int(str(n)[::-1])
    return is_prime(n) and is_prime(rev) and rev != n

def is_palindromic_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    s = str(n)
    return is_prime(n) and s == s[::-1]

def is_twin_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    if not is_prime(n):
        return False
    return is_prime(n - 2) or is_prime(n + 2)

def sum_twin_primes_below(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    total = 0
    for p in range(2, n):
        if is_prime(p) and (is_prime(p - 2) or is_prime(p + 2)):
            total += p
    return total

def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    primes = []
    cand = 2
    while len(primes) < n + 1:
        if is_prime(cand):
            primes.append(cand)
        cand += 1
    return primes[n] - primes[n - 1]
